contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 shareAmount, address to) public {
        require(shareAmount > 0, "zero shares");
        uint256 supplyBefore = c.totalSupply();
        require(supplyBefore > 0, "no shares");
        require(shareAmount <= c.balanceOf(address(this)), "insufficient shares");

        uint256 baseBalanceBefore = c.getVaultReserve(); // only returns baseReserve, quoteReserve? Actually returns tuple
        // getVaultReserve() returns (uint256 baseReserve, uint256 quoteReserve)
        // Need to destructure
        (uint256 baseReserveBefore, uint256 quoteReserveBefore) = c.getVaultReserve();
        uint256 mtFeeBaseBefore = c._MT_FEE_BASE_();
        uint256 mtFeeQuoteBefore = c._MT_FEE_QUOTE_();
        uint256 baseBalanceBefore = baseReserveBefore + mtFeeBaseBefore;
        uint256 quoteBalanceBefore = quoteReserveBefore + mtFeeQuoteBefore;

        uint256 baseMinAmount = 0;
        uint256 quoteMinAmount = 0;
        bytes memory data = new bytes(0);
        uint256 deadline = block.timestamp;

        bool reverted;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 baseAmount, uint256 quoteAmount) {
            reverted = false;
            // Check invariants after successful sell
            uint256 supplyAfter = c.totalSupply();
            uint256 baseReserveAfter;
            uint256 quoteReserveAfter;
            (baseReserveAfter, quoteReserveAfter) = c.getVaultReserve();
            // The rule: the sum of base and quote amounts returned must be <= the respective balances before the call
            assert(baseAmount * supplyBefore <= baseBalanceBefore * (supplyBefore - supplyAfter) || baseAmount <= baseBalanceBefore);
            // Better rule: baseAmount + quoteAmount <= total balance? Not necessarily.
            // Let's use a simpler general rule: the contract's total base balance (reserve + fee) must not decrease by more than the amount withdrawn.
            // Actually selling shares burns shares and withdraws proportional amount. The invariant is that the contract always maintains at least the proportional share of reserves for the remaining shares.
            // A safe rule: baseAmount <= baseBalanceBefore (since baseAmount = baseBalance * shareAmount / totalShares, and shareAmount <= totalShares)
            // Similarly quoteAmount <= quoteBalanceBefore.
            assert(baseAmount <= baseBalanceBefore);
            assert(quoteAmount <= quoteBalanceBefore);
        } catch {
            reverted = true;
            assert(true);
        }
    }

    receive() external payable {}
}

