        require(true);

        // Record recipient's share balance before buyShares.
        uint256 sharesBefore = c.balanceOf(to);

        // Attempt the buyShares call. It may revert; the bound variables remain unset on revert.
        uint256 shares = 0;
        bool buySucceeded = false;
