contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shareAmount, uint256 seedBase, uint256 seedQuote, uint256 baseMinAmount, uint256 quoteMinAmount) public payable {
        require(seedBase > 0 && seedQuote > 0, "SEED_ZERO");
        require(shareAmount > 0, "ZERO_SHARES");

        // Seed reserves and initial shares by minting shares.
        // The test contract owns all initial shares, so it can sell them.
        c.buyShares(address(this));

        uint256 preTotalSupply = c.totalSupply();
        uint256 preBaseBalance = c.balanceOf(address(this));
        uint256 preBaseReserve = uint256(c._BASE_RESERVE_());
        uint256 preQuoteReserve = uint256(c._QUOTE_RESERVE_());
        require(shareAmount <= preBaseBalance, "INSUFFICIENT_SHARES");

        uint256 expectedBaseAmount = preBaseReserve * shareAmount / preTotalSupply;
        uint256 expectedQuoteAmount = preQuoteReserve * shareAmount / preTotalSupply;

        // The sell should succeed if the proportional payout meets the minimums.
        c.sellShares(shareAmount, address(this), baseMinAmount, quoteMinAmount, "", block.timestamp);

        uint256 postTotalSupply = c.totalSupply();
        uint256 postBaseBalance = c.balanceOf(address(this));
        uint256 postBaseReserve = uint256(c._BASE_RESERVE_());
        uint256 postQuoteReserve = uint256(c._QUOTE_RESERVE_());

        assert(
            postTotalSupply == preTotalSupply - shareAmount &&
            postBaseBalance == preBaseBalance - shareAmount &&
            preBaseReserve - postBaseReserve == expectedBaseAmount &&
            preQuoteReserve - postQuoteReserve == expectedQuoteAmount &&
            expectedBaseAmount >= baseMinAmount &&
            expectedQuoteAmount >= quoteMinAmount
        );
    }

    receive() external payable {}
}
